import{_ as l,o as e,c as i,a2 as a}from"./chunks/framework.CFuv5BrO.js";const _=JSON.parse('{"title":"默认审批与完成清单","description":"Hearth 默认审批清单、默认完成清单与任务覆盖的最终定义。","frontmatter":{"title":"默认审批与完成清单","description":"Hearth 默认审批清单、默认完成清单与任务覆盖的最终定义。","outline":[2,3]},"headers":[],"relativePath":"reference/checklists.md","filePath":"reference/checklists.md","lastUpdated":1793706118000}'),r={name:"reference/checklists.md"};function d(o,t,s,n,c,h){return e(),i("div",null,[...t[0]||(t[0]=[a('<p class="eyebrow">CHECKLISTS</p><h1 id="默认审批与完成清单" tabindex="-1">默认审批与完成清单 <a class="header-anchor" href="#默认审批与完成清单" aria-label="Permalink to &quot;默认审批与完成清单&quot;">​</a></h1><p class="lead">把这些清单放进任务模板、审批界面和验收流程，而不是留在文档里。</p><h2 id="默认审批清单" tabindex="-1">默认审批清单 <a class="header-anchor" href="#默认审批清单" aria-label="Permalink to &quot;默认审批清单&quot;">​</a></h2><p>高风险动作前，逐项确认：</p><ul><li>[ ] 动作类型正确；</li><li>[ ] 目标收件人/文件/仓库/日历/资源正确；</li><li>[ ] 使用账户正确；</li><li>[ ] 内容和附件正确；</li><li>[ ] 范围没有超出 Mandate；</li><li>[ ] 是否可逆已说明；</li><li>[ ] 失败和对账方式已说明；</li><li>[ ] 审批有 nonce 和过期时间；</li><li>[ ] 已准备回执和撤销/补偿；</li><li>[ ] 没有绕过安全控制。</li></ul><h2 id="默认完成清单" tabindex="-1">默认完成清单 <a class="header-anchor" href="#默认完成清单" aria-label="Permalink to &quot;默认完成清单&quot;">​</a></h2><p>任务标记完成前，逐项确认：</p><ul><li>[ ] 目标产物存在且可定位；</li><li>[ ] 验证器通过；</li><li>[ ] 关键断言有来源；</li><li>[ ] 修改有 diff 或版本；</li><li>[ ] 没有未授权的副作用；</li><li>[ ] 外部动作有 Receipt；</li><li>[ ] 失败和未完成项已说明；</li><li>[ ] Token、时间和成本已记录；</li><li>[ ] 工作区、凭据和 lease 已回收；</li><li>[ ] 用户可以查看、撤销或继续。</li></ul><h2 id="任务覆盖的最终定义" tabindex="-1">任务覆盖的最终定义 <a class="header-anchor" href="#任务覆盖的最终定义" aria-label="Permalink to &quot;任务覆盖的最终定义&quot;">​</a></h2><p>Hearth 的目标不是承诺“任何软件、任何场景、100% 无人值守”。它的目标是：</p><ul><li>对八类数字内容工作提供端到端覆盖；</li><li>对每类任务逐步提高可靠性和自主性；</li><li>对无法可靠完成的任务安全停下并交给人；</li><li>让用户不必理解内部架构，也不必重复交代上下文；</li><li>让每次完成都有证据、权限和回执。</li></ul><p>覆盖的成熟度应分层表述：</p><table tabindex="0"><thead><tr><th>层级</th><th>含义</th></tr></thead><tbody><tr><td>可尝试</td><td>系统能进入该任务族并产生草稿</td></tr><tr><td>可完成</td><td>在代表性任务上通过验证</td></tr><tr><td>可依赖</td><td>多次真实使用稳定，失败可恢复</td></tr><tr><td>可主动</td><td>在 Mandate 内无需人工触发</td></tr><tr><td>可无人值守</td><td>长时间运行且风险可控</td></tr></tbody></table><p>不要用“可尝试”冒充“可无人值守”。</p>',15)])])}const u=l(r,[["render",d]]);export{_ as __pageData,u as default};
